package io.mosip.injivcrenderer.templateEngine.svg

/**
 * Embedded portrait shown when an SVG image href is missing or not a renderable
 * data URI. Batik loads this from the document itself, so PDF generation does not
 * try to fetch an external resource.
 *
 * The PNG is 24-bit RGB. Batik's PDF transcoder rejects some 32-bit PNG variants
 * with "readRaster not supported".
 */
internal object NoImagePlaceholder {
    const val DATA_URI = "data:image/png;base64,"
}
